for pkg in $(pm list packages -3 | cut -f 2 -d ":"); do echo "$pkg" | grep -vE "frb.axeron.manager|ia.mo" > /dev/null && am force-stop "$pkg"; done; am kill-all; cmd activity kill-all; cmd package trim-caches 999G;for a in android com.android.systemui; do pid=$(pgrep -f "$a"); [ ! -z "$pid" ] && chrt -f -p 99 "$pid" && taskset -p ff "$pid" && cmd activity clear-exit-info "$a"; done ; exit 0